create table if not exists public.products(id bigint generated by default as identity primary key,name text not null,category text not null,sale_price numeric(10,2) not null default 0,cost_price numeric(10,2) not null default 0,asset text not null default '',sort_order integer not null default 0,active boolean not null default true);
create table if not exists public.sales(id bigint generated by default as identity primary key,created_at timestamptz not null default now(),payment_method text not null,total numeric(10,2) not null,cost numeric(10,2) not null default 0);
create table if not exists public.sale_items(id bigint generated by default as identity primary key,sale_id bigint not null references public.sales(id) on delete cascade,product_id bigint references public.products(id),product_name text not null,quantity integer not null,unit_price numeric(10,2) not null,unit_cost numeric(10,2) not null default 0);
alter table public.products enable row level security;alter table public.sales enable row level security;alter table public.sale_items enable row level security;
